#include <iostream>
using namespace std;

int calculate_fuel(int distance, int burn_rate) {
    return distance * burn_rate;
}

int main() {
    int dist, rate;
    cin >> dist >> rate;

    int fuel_needed = calculate_fuel(dist, rate);
    cout << "FUEL REQUIRED: " << fuel_needed << endl;

    return 0;
}

